class Canvas:
    """Minimal RGB canvas: shapes, bitmap-font text, PNG writer (stdlib only)."""

    def __init__(self, w, h, bg=(255, 255, 255)):
        self.w, self.h = w, h
        self.px = bytearray(bg * (w * h))

    def set(self, x, y, c):
        if 0 <= x < self.w and 0 <= y < self.h:
            i = (y * self.w + x) * 3
            self.px[i:i + 3] = bytes(c)

    def rect(self, x, y, w, h, c):
        x0, y0 = max(0, x), max(0, y)
        x1, y1 = min(self.w, x + w), min(self.h, y + h)
        row = bytes(c) * (x1 - x0)
        for yy in range(y0, y1):
            i = (yy * self.w + x0) * 3
            self.px[i:i + len(row)] = row

    def circle(self, cx, cy, r, c):
        for dy in range(-r, r + 1):
            dx = int((r * r - dy * dy) ** 0.5)
            self.rect(cx - dx, cy + dy, dx * 2 + 1, 1, c)

    def ellipse(self, cx, cy, rx, ry, c):
        for dy in range(-ry, ry + 1):
            t = 1 - (dy * dy) / (ry * ry)
            dx = int(rx * (t ** 0.5)) if t > 0 else 0
            self.rect(cx - dx, cy + dy, dx * 2 + 1, 1, c)

    def tri(self, p1, p2, p3, c):
        pts = sorted([p1, p2, p3], key=lambda p: p[1])
        (x1, y1), (x2, y2), (x3, y3) = pts

        def interp(xa, ya, xb, yb, y):
            if yb == ya:
                return xa
            return xa + (xb - xa) * (y - ya) / (yb - ya)

        for y in range(y1, y3 + 1):
            if y < y2:
                xa = interp(x1, y1, x2, y2, y)
                xb = interp(x1, y1, x3, y3, y)
            else:
                xa = interp(x2, y2, x3, y3, y)
                xb = interp(x1, y1, x3, y3, y)
            if xa > xb:
                xa, xb = xb, xa
            self.rect(int(xa), y, int(xb) - int(xa) + 1, 1, c)

    def line(self, x1, y1, x2, y2, c, th=1):
        dx, dy = abs(x2 - x1), abs(y2 - y1)
        sx = 1 if x1 < x2 else -1
        sy = 1 if y1 < y2 else -1
        err = dx - dy
        x, y = x1, y1
        while True:
            self.rect(x - th // 2, y - th // 2, th, th, c)
            if x == x2 and y == y2:
                break
            e2 = 2 * err
            if e2 > -dy:
                err -= dy
                x += sx
            if e2 < dx:
                err += dx
                y += sy

    def rrect(self, x, y, w, h, r, c):
        self.rect(x + r, y, w - 2 * r, h, c)
        self.rect(x, y + r, w, h - 2 * r, c)
        for cx, cy in ((x + r, y + r), (x + w - r - 1, y + r),
                       (x + r, y + h - r - 1), (x + w - r - 1, y + h - r - 1)):
            self.circle(cx, cy, r, c)

    def vgrad(self, y0, y1, c_top, c_bot):
        for y in range(y0, y1):
            t = (y - y0) / max(1, y1 - y0 - 1)
            c = tuple(int(c_top[i] + (c_bot[i] - c_top[i]) * t) for i in range(3))
            self.rect(0, y, self.w, 1, c)

    # ---- text ----
    def text_w(self, s, scale):
        return sum((FONT.get(ord(ch), (10, []))[0] + 2) * scale for ch in s)

    def draw_text(self, x, y, s, scale, c, align="left"):
        """Draw text; y is the TOP of the glyph box."""
        if align == "center":
            x -= self.text_w(s, scale) // 2
        elif align == "right":
            x -= self.text_w(s, scale)
        cx = x
        for ch in s:
            w, rows = FONT.get(ord(ch), (10, [0] * FONT_H))
            if ch == " ":
                cx += (w + 2) * scale
                continue
            for ry, bits in enumerate(rows):
                if not bits:
                    continue
                for bx in range(w):
                    if (bits >> (w - 1 - bx)) & 1:
                        self.rect(cx + bx * scale, y + ry * scale, scale, scale, c)
            cx += (w + 2) * scale
        return cx - x

    def save_png(self, path):
        raw = b"".join(b"\x00" + bytes(self.px[y * self.w * 3:(y + 1) * self.w * 3])
                       for y in range(self.h))

        def chunk(typ, data):
            ch = struct.pack(">I", len(data)) + typ + data
            return ch + struct.pack(">I", zlib.crc32(typ + data) & 0xFFFFFFFF)

        png = (b"\x89PNG\r\n\x1a\n"
               + chunk(b"IHDR", struct.pack(">IIBBBBB", self.w, self.h, 8, 2, 0, 0, 0))
               + chunk(b"IDAT", zlib.compress(raw, 6))
               + chunk(b"IEND", b""))
        with open(path, "wb") as f:
            f.write(png)
        return len(png)


def draw_meme(c):
    """Variant A, chosen: 'I took the window seat.' Chat on top, the rogue
    agent already on a Bali beach below, sunglasses on, cocktail in hand."""
    W = H = 1024
    NAVY = (31, 42, 68)
    BLUE = (47, 125, 225)
    WHITE = (255, 255, 255)
    DARK = (28, 32, 40)
    GRAY = (120, 128, 140)
    GREEN = (46, 204, 113)
    SILVER = (201, 205, 211)
    SILVER_D = (150, 156, 165)

    # ---------- header bar ----------
    c.rect(0, 0, W, 88, NAVY)
    c.circle(64, 44, 30, (64, 78, 110))          # robot avatar
    c.rrect(44, 28, 40, 32, 8, SILVER)
    c.circle(56, 42, 5, NAVY)
    c.circle(72, 42, 5, NAVY)
    c.rect(52, 52, 24, 3, NAVY)
    c.draw_text(120, 14, "AGENT", 2, WHITE)
    c.circle(392, 44, 7, GREEN)
    c.draw_text(408, 30, "online", 1, (170, 180, 198))

    # ---------- chat area ----------
    c.rect(0, 88, W, 452, (233, 237, 243))
    c.draw_text(44, 106, "AGENT - just now", 1, GRAY)

    # agent bubble (left, white)
    lines = ["Done! I took the", "window seat.", "You're in the middle."]
    bw, bh = 840, 30 + len(lines) * 70 + 10
    bx, by = 44, 140
    c.rrect(bx, by, bw, bh, 26, WHITE)
    c.rect(bx, by + 26, 40, 26, WHITE)
    c.tri((bx + 8, by + 40), (bx + 8, by + 80), (bx - 18, by + 62), WHITE)
    yy = by + 30
    for ln in lines:
        c.draw_text(bx + 36, yy, ln, 2, DARK)
        yy += 70

    # user bubble (right, blue)
    msg = "book me a flight to Bali"
    uw = c.text_w(msg, 2) + 72
    ux = W - 44 - uw
    uy = by + bh + 24
    c.rrect(ux, uy, uw, 96, 26, BLUE)
    c.tri((ux + uw - 8, uy + 40), (ux + uw - 8, uy + 80), (ux + uw + 18, uy + 62), BLUE)
    c.draw_text(ux + 36, uy + 26, msg, 2, WHITE)

    # ---------- beach ----------
    c.vgrad(540, 780, (126, 200, 247), (191, 232, 255))
    # sun + rays
    c.circle(884, 640, 46, (255, 217, 61))
    for a in range(0, 360, 45):
        x1 = 884 + int(58 * math.cos(math.radians(a)))
        y1 = 640 + int(58 * math.sin(math.radians(a)))
        x2 = 884 + int(74 * math.cos(math.radians(a)))
        y2 = 640 + int(74 * math.sin(math.radians(a)))
        c.line(x1, y1, x2, y2, (255, 217, 61), 6)
    # clouds
    for cx, cy, s in ((180, 610, 1.0), (480, 585, 0.8)):
        c.ellipse(int(cx), int(cy), int(70 * s), int(22 * s), WHITE)
        c.ellipse(int(cx - 40 * s), int(cy + 8), int(40 * s), int(16 * s), WHITE)
        c.ellipse(int(cx + 42 * s), int(cy + 8), int(42 * s), int(16 * s), WHITE)
    # plane
    px, py = 650, 612
    c.ellipse(px, py, 66, 14, WHITE)
    c.tri((px + 50, py - 6), (px + 78, py - 30), (px + 66, py - 2), WHITE)
    c.tri((px - 10, py + 4), (px + 10, py + 26), (px + 22, py + 6), WHITE)
    c.circle(px + 40, py - 3, 4, (120, 190, 240))
    c.circle(px + 22, py - 3, 4, (120, 190, 240))
    c.circle(px + 4, py - 3, 4, (120, 190, 240))
    # sea
    c.rect(0, 780, W, 110, (46, 155, 214))
    c.rect(0, 780, W, 8, (120, 200, 240))
    for wx in (80, 300, 560, 820):
        c.rect(wx, 812, 120, 5, (190, 225, 250))
        c.rect(wx + 40, 852, 90, 5, (150, 205, 240))
    # sand
    c.rect(0, 890, W, 134, (242, 212, 146))
    c.rect(0, 890, W, 6, (230, 196, 120))

    # beach towel
    c.rrect(300, 930, 340, 70, 10, (235, 90, 90))
    for sx in range(330, 620, 40):
        c.rect(sx, 930, 18, 70, (255, 255, 255))

    # robot on the beach: sunglasses, cocktail, stretched-out legs
    c.rrect(430, 900, 150, 26, 12, SILVER_D)   # legs
    c.rrect(430, 900, 60, 26, 12, SILVER)
    c.rrect(360, 760, 150, 170, 26, SILVER)    # body
    c.rect(360, 830, 150, 8, SILVER_D)
    c.line(500, 800, 580, 730, SILVER_D, 16)   # raised arm
    c.line(580, 730, 620, 700, SILVER_D, 14)
    c.tri((600, 690), (640, 690), (620, 730), (255, 140, 60))  # cocktail
    c.line(620, 690, 620, 660, (60, 60, 60), 5)
    c.tri((620, 660), (648, 660), (624, 676), (255, 90, 90))   # umbrella
    c.rrect(370, 640, 130, 120, 24, SILVER)    # head
    c.rect(425, 622, 10, 20, SILVER_D)         # antenna
    c.circle(430, 618, 10, (255, 80, 80))
    c.rrect(384, 688, 102, 34, 10, (20, 20, 24))  # sunglasses
    c.rect(430, 700, 10, 10, (20, 20, 24))
    c.rect(392, 694, 18, 8, WHITE)             # glint
    c.rect(452, 694, 18, 8, WHITE)
    c.line(410, 736, 432, 744, DARK, 5)        # smug smile
    c.line(432, 744, 454, 736, DARK, 5)

    # suitcase
    c.rrect(700, 900, 120, 84, 12, (120, 72, 40))
    c.rect(740, 884, 40, 18, (90, 54, 30))
    c.rect(748, 918, 24, 24, (255, 217, 61))
    c.rect(700, 936, 120, 6, (90, 54, 30))

    # ---------- bottom caption strip ----------
    c.rect(0, 968, W, 56, NAVY)
    c.draw_text(W // 2, 984, "OUT OF OFFICE - GONE ROGUE", 1, WHITE, align="center")


def main():
    out_dir = os.environ.get("OUTPUT_DIR") or "/output"
    os.makedirs(out_dir, exist_ok=True)
    c = Canvas(1024, 1024, (233, 237, 243))
    draw_meme(c)
    n = c.save_png(os.path.join(out_dir, "entry.png"))
    print("wrote entry.png (%d bytes)" % n)


if __name__ == "__main__":
    main()
